import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Separate UI document; never modifies app.sab, kits or component meta. */
final class ViewStore {
 static final int LIMIT=512*1024;
 static final Path ROOT=Paths.get("data/ui-projects");
 static String id(Object value){if(!(value instanceof String))throw new IllegalArgumentException("Invalid UI project ID");String s=(String)value;if(!s.matches("[a-zA-Z0-9_-]{1,64}"))throw new IllegalArgumentException("Invalid UI project ID");return s;}
 static byte[] encode(Map<String,Object> document){
  if(!"mcs-sedona-ui".equals(document.get("format"))||!(document.get("version") instanceof Number)||!Set.of(1.0,2.0,3.0).contains(((Number)document.get("version")).doubleValue()))throw new IllegalArgumentException("Unknown UI format");
  id(document.get("id"));if(!(document.get("views") instanceof List)||((List<?>)document.get("views")).size()>128)throw new IllegalArgumentException("Invalid UI views");
  if(!(Set.of("format","version","id","title","views","library","components").containsAll(document.keySet())&&document.keySet().containsAll(Set.of("format","version","id","title","views")))||!(document.get("title") instanceof String)||((String)document.get("title")).length()>128)throw new IllegalArgumentException("Invalid UI fields");
  int version=((Number)document.get("version")).intValue();if(document.containsKey("library")&&version<2)throw new IllegalArgumentException("SVG library requires UI format v2");
  if(document.containsKey("components")&&version!=3)throw new IllegalArgumentException("Graphic components require UI format v3");
  Set<String> assets=document.containsKey("library")?SvgLibraryRules.library(document.get("library")):Collections.emptySet();
  Map<String,Map<String,String>> components=document.containsKey("components")?ComponentRules.components(document.get("components"),assets):Collections.emptyMap();
  Set<String> ids=new HashSet<>();for(Object item:(List<?>)document.get("views")){if(!(item instanceof Map))throw new IllegalArgumentException("Invalid UI view");Map<?,?> view=(Map<?,?>)item;if(!(Set.of("id","title","folder","svg","widgets","objects","parts").containsAll(view.keySet())&&view.keySet().containsAll(Set.of("id","title","folder","svg")))||!ids.add(id(view.get("id"))))throw new IllegalArgumentException("Invalid or duplicate view");for(String field:List.of("title","folder","svg"))if(!(view.get(field) instanceof String))throw new IllegalArgumentException("Invalid view field");if(((String)view.get("title")).length()>128||((String)view.get("folder")).length()>2048)throw new IllegalArgumentException("View field too long");if(view.containsKey("widgets"))validateWidgets(view.get("widgets"));if(view.containsKey("objects")&&version<2)throw new IllegalArgumentException("SVG scene requires UI format v2");if(view.containsKey("objects"))SvgLibraryRules.objects(view.get("objects"),assets);if(view.containsKey("parts")){if(version!=3)throw new IllegalArgumentException("Placed components require UI format v3");ComponentRules.parts(view.get("parts"),components);}}
  byte[] bytes=Json.write(document).getBytes(StandardCharsets.UTF_8);if(bytes.length>LIMIT)throw new IllegalArgumentException("UI package exceeds 512 KiB");return bytes;
 }
 static void validateWidgets(Object value){
  if(!(value instanceof List)||((List<?>)value).size()>64)throw new IllegalArgumentException("Maximum 64 widgets per view");Set<String> ids=new HashSet<>();
  for(Object item:(List<?>)value){if(!(item instanceof Map))throw new IllegalArgumentException("Invalid widget");Map<?,?> w=(Map<?,?>)item;if(!w.keySet().containsAll(Set.of("id","kind","label","path","slot","type","x","y","unit","decimals"))||!Set.of("id","kind","label","path","slot","type","x","y","unit","decimals","appearance","width","fontSize","min","max","showLabel","showUnit","showQuality","border","background","command","height","series","windowSeconds","sampleSeconds","autoScale","legend").containsAll(w.keySet())||!ids.add(id(w.get("id")))||!Set.of("value","indicator","setpoint","toggle","button","bar","gauge","slider","text","trend","bars","table").contains(w.get("kind")))throw new IllegalArgumentException("Invalid widget fields");
   if(w.containsKey("appearance")&&!Set.of("card","compact","value","lamp").contains(w.get("appearance")))throw new IllegalArgumentException("Invalid widget appearance");
   for(String key:List.of("showLabel","showUnit","showQuality","border","background","command","autoScale","legend"))if(w.containsKey(key)&&!(w.get(key) instanceof Boolean))throw new IllegalArgumentException("Invalid widget flag");
   for(String key:List.of("width","fontSize","min","max","height","windowSeconds","sampleSeconds"))if(w.containsKey(key)){Object n=w.get(key);double low=key.equals("width")?40:key.equals("fontSize")?10:key.equals("height")?100:key.equals("windowSeconds")?10:key.equals("sampleSeconds")?1:-1e9,high=key.equals("width")?900:key.equals("fontSize")?72:key.equals("height")?600:key.equals("windowSeconds")?3600:key.equals("sampleSeconds")?60:1e9;if(!(n instanceof Number)||!Double.isFinite(((Number)n).doubleValue())||((Number)n).doubleValue()<low||((Number)n).doubleValue()>high)throw new IllegalArgumentException("Invalid widget range");}
   if(w.containsKey("series")){Object channels=w.get("series");if(!(channels instanceof List)||((List<?>)channels).size()>8)throw new IllegalArgumentException("Maximum 8 channels");for(Object channel:(List<?>)channels){if(!(channel instanceof Map))throw new IllegalArgumentException("Invalid channel");Map<?,?> c=(Map<?,?>)channel;if(!Set.of("path","slot","type","label","unit","color").containsAll(c.keySet())||!c.keySet().containsAll(Set.of("path","slot","type","label","unit")))throw new IllegalArgumentException("Invalid channel fields");for(String key:List.of("path","slot","type","label","unit"))if(!(c.get(key) instanceof String)||((String)c.get(key)).length()>(key.equals("path")?2048:key.equals("type")?160:key.equals("unit")?32:128))throw new IllegalArgumentException("Invalid channel text");String path=(String)c.get("path"),slot=(String)c.get("slot");if(path.isEmpty()||Arrays.stream(path.split("/",-1)).anyMatch(v->v.isEmpty()||v.equals(".."))||slot.isEmpty()||slot.equals("meta")||slot.matches("(?i).*(password|secret|cred).*|(?i)key"))throw new IllegalArgumentException("Invalid channel binding");if(c.containsKey("color")&&(!(c.get("color") instanceof String)||!((String)c.get("color")).matches("#[0-9a-fA-F]{6}")))throw new IllegalArgumentException("Invalid channel color");}}
   double low=w.containsKey("min")?((Number)w.get("min")).doubleValue():0,high=w.containsKey("max")?((Number)w.get("max")).doubleValue():100;if(high<=low)throw new IllegalArgumentException("Invalid widget scale");
   for(String key:List.of("label","path","slot","type","unit"))if(!(w.get(key) instanceof String)||((String)w.get(key)).length()>(key.equals("path")?2048:key.equals("unit")?32:key.equals("type")?160:128))throw new IllegalArgumentException("Invalid widget text");
   String path=(String)w.get("path"),slot=(String)w.get("slot");if(path.isEmpty()||Arrays.stream(path.split("/",-1)).anyMatch(p->p.isEmpty()||p.equals(".."))||slot.isEmpty()||slot.equals("meta")||slot.matches("(?i).*(password|secret|cred).*|(?i)key"))throw new IllegalArgumentException("Invalid widget binding");
   for(String key:List.of("x","y","decimals")){Object n=w.get(key);if(!(n instanceof Number))throw new IllegalArgumentException("Invalid widget coordinate");double d=((Number)n).doubleValue();if(!Double.isFinite(d)||d<0||d>(key.equals("decimals")?6:100)||key.equals("decimals")&&d!=Math.rint(d))throw new IllegalArgumentException("Widget coordinate out of range");}
  }
 }
 static Map<String,Object> decode(byte[] bytes){if(bytes.length>LIMIT)throw new IllegalArgumentException("UI package exceeds 512 KiB");Map<String,Object> doc=Json.object(new String(bytes,StandardCharsets.UTF_8));encode(doc);return doc;}
 static synchronized Map<String,Object> save(Map<String,Object> doc)throws Exception{
  byte[] bytes=encode(doc);Files.createDirectories(ROOT);Path target=ROOT.resolve(id(doc.get("id"))+".json");
  if(Files.exists(target)){Path backups=ROOT.resolve("backups");Files.createDirectories(backups);Files.copy(target,backups.resolve(id(doc.get("id"))+"-"+UUID.randomUUID()+".json"));}
  Path temp=Files.createTempFile(ROOT,"ui-",".tmp");try{Files.write(temp,bytes);try{Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}
  return DeviceGateway.map("saved",true,"path",target.toString(),"bytes",bytes.length);
 }
 static Map<String,Object> read(Path path)throws Exception{if(Files.size(path)>LIMIT)throw new IllegalArgumentException("UI package exceeds 512 KiB");return decode(Files.readAllBytes(path));}
 static synchronized Map<String,Object> load(String id)throws Exception{return read(ROOT.resolve(id(id)+".json"));}
 static synchronized List<Object> list()throws Exception{List<Object> out=new ArrayList<>();if(Files.isDirectory(ROOT))try(var files=Files.list(ROOT)){for(Path p:files.filter(p->p.getFileName().toString().endsWith(".json")).sorted().toList())try{Map<String,Object>d=read(p);out.add(DeviceGateway.map("id",d.get("id"),"title",d.get("title")));}catch(Exception e){System.err.println("Skipped invalid UI package: "+p.getFileName());}}return out;}
}
